import { useEffect, useState } from "react";
import API from "../services/api";
import UnifiedNavbar from "../components/UnifiedNavbar";

function ManageMenu() {

const [menus,setMenus] = useState([]);

const [day,setDay] = useState("");
const [breakfast,setBreakfast] = useState("");
const [lunch,setLunch] = useState("");
const [dinner,setDinner] = useState("");

const [editId,setEditId] = useState(null);


useEffect(()=>{

// Get user role from localStorage
const storedUser = localStorage.getItem("user");
if (storedUser) {
  try {
    const user = JSON.parse(storedUser);
    setUserRole(user.role ? user.role.toLowerCase() : "staff");
  } catch (e) {
    setUserRole("staff");
  }
}

fetchMenus();

},[]);


const fetchMenus = async () => {

const res = await API.get("/menu");

setMenus(res.data);

};


const saveMenu = async () => {

if(editId){

await API.put(`/menu/${editId}`,{
day,
breakfast,
lunch,
dinner
});

}else{

await API.post("/menu",{
day,
breakfast,
lunch,
dinner
});

}

setDay("");
setBreakfast("");
setLunch("");
setDinner("");
setEditId(null);

fetchMenus();

};


const editMenu = (menu) => {

setEditId(menu.id);

setDay(menu.day);
setBreakfast(menu.breakfast);
setLunch(menu.lunch);
setDinner(menu.dinner);

};


const deleteMenu = async (id) => {

await API.delete(`/menu/${id}`);

fetchMenus();

};


return (

<div className="dashboard">

{userRole === "admin" ? <AdminNavbar /> : <StaffNavbar />}

<div className="main-content">

<h1>Menu Management</h1>


{/* ADD MENU FORM */}

<div className="menu-form">

<input
placeholder="Day (Monday)"
value={day}
onChange={(e)=>setDay(e.target.value)}
/>

<input
placeholder="Breakfast"
value={breakfast}
onChange={(e)=>setBreakfast(e.target.value)}
/>

<input
placeholder="Lunch"
value={lunch}
onChange={(e)=>setLunch(e.target.value)}
/>

<input
placeholder="Dinner"
value={dinner}
onChange={(e)=>setDinner(e.target.value)}
/>

<button onClick={saveMenu}>

{editId ? "Update Menu" : "Add Menu"}

</button>

</div>


{/* MENU TABLE */}

<div className="menu-list">

<h2>All Menus</h2>

<table className="menu-table">

<thead>

<tr>

<th>Day</th>
<th>Breakfast</th>
<th>Lunch</th>
<th>Dinner</th>
<th>Actions</th>

</tr>

</thead>

<tbody>

{menus.map((m)=> (

<tr key={m.id}>

<td>{m.day}</td>
<td>{m.breakfast}</td>
<td>{m.lunch}</td>
<td>{m.dinner}</td>

<td>

<div className="menu-actions">

<button
className="menu-edit"
onClick={()=>editMenu(m)}
>
Edit
</button>

<button
className="menu-delete"
onClick={()=>deleteMenu(m.id)}
>
Delete
</button>

</div>

</td>

</tr>

))}

</tbody>

</table>

</div>

</div>

</div>

)

}

export default ManageMenu;
